const touchIndexTopic = `-- name: TouchIndexTopic :one
UPDATE topics t SET index_updated_at = clock_timestamp()
WHERE t.id = $1
RETURNING t.id, t.place_id, t.board_id, (t.deleted_at IS NOT NULL)::boolean AS deleted,
    COALESCE((SELECT b.in_index FROM boards b WHERE b.id = t.board_id), false)::boolean AS board_in_index,
    EXISTS (
        SELECT 1 FROM posts op JOIN users u ON u.id = op.author_id
        WHERE op.topic_id = t.id AND op.post_number = 1 AND op.deleted_at IS NULL
          AND u.deleted_at IS NULL AND NOT u.exclude_from_index
    )::boolean AS opening_visible
`

type TouchIndexTopicRow struct {
	ID             uuid.UUID
	PlaceID        uuid.UUID
	BoardID        uuid.UUID
	Deleted        bool
	BoardInIndex   bool
	OpeningVisible bool
}

// Bumps the topic's index timestamp and reports whether it is indexable now.
func (q *Queries) TouchIndexTopic(ctx context.Context, id uuid.UUID) (TouchIndexTopicRow, error) {
	row := q.db.QueryRow(ctx, touchIndexTopic, id)
	var i TouchIndexTopicRow
	err := row.Scan(
		&i.ID,
		&i.PlaceID,
		&i.BoardID,
		&i.Deleted,
		&i.BoardInIndex,
		&i.OpeningVisible,
	)
	return i, err
}

const touchUserTopics = `-- name: TouchUserTopics :exec
UPDATE topics SET index_updated_at = clock_timestamp()
WHERE id IN (SELECT p.topic_id FROM posts p WHERE p.author_id = $1 AND p.deleted_at IS NULL)
  AND deleted_at IS NULL
`

func (q *Queries) TouchUserTopics(ctx context.Context, userID *uuid.UUID) error {
	_, err := q.db.Exec(ctx, touchUserTopics, userID)
	return err
}

const userHasIndexedPosts = `-- name: UserHasIndexedPosts :one
SELECT EXISTS (
    SELECT 1 FROM posts p JOIN boards b ON b.id = p.board_id
    WHERE p.author_id = $1 AND p.deleted_at IS NULL AND b.in_index
)::boolean
`

func (q *Queries) UserHasIndexedPosts(ctx context.Context, userID *uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, userHasIndexedPosts, userID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
